### Testcase Gist URL

Not able to create the fiddle right now, but there is a code example in the additional information.

### Additional Information

Confirmed that the transparency is working when using BrowserWindow.

package.json
``` json
{
  "name": "transparency-bug",
  "version": "1.0.0",
  "private": true,
  "main": "main.js",
  "scripts": {
    "start": "electron ."
  },
  "devDependencies": {
    "electron": "=41.0.4"
  }
}
```

main.js
``` js
const { app, BaseWindow, WebContentsView } = require('electron');

function createWindow() {
  const win = new BaseWindow({ width: 800, height: 600, transparent: true, frame: false });
  const view = new WebContentsView();
  win.contentView.addChildView(view);
  view.setBounds({ x: 0, y: 0, width: 800, height: 600 });
  view.webContents.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(`<!doctype html><html><head><style>body{height:100%;margin:0;background:rgba(1,1,1,.5);}</style></head><body></body></html>`));
}

app.whenReady().then(createWindow);
app.on('window-all-closed', app.quit);

```
A frameless window is not required but it is easier to notice the issue.

